//! Integration tests for the `image` crate: zlib/DEFLATE vectors, the PNG
//! fixture matrix, the real pipeline PNG and robustness/fuzz smoke tests.
//!
//! The PNG fixtures are generated by `tests/fixtures/generate.py` with Python's
//! `zlib`/`binascii` (an independent encoder); `basic.png` is the output of the
//! Megi HTML→PNG pipeline for `tests/fixtures/phase4/basic.html`.

include!("data/zlib_vectors.rs");

use image::{
    ImageError, ImageFormat, InflateLimits, PngLimits, decode, decode_with_limits, detect_format,
    inflate_deflate, inflate_zlib,
};

/// Expected bytes of the `DYNAMIC` zlib vector (same generation as
/// `generate.py`).
fn dynamic_expected() -> Vec<u8> {
    let mut expected: Vec<u8> = (0..600u32)
        .map(|index| ((index * 37 + (index / 8) * 11) & 0xFF) as u8)
        .collect();
    for _ in 0..40 {
        expected.extend_from_slice(b"repeat-me ");
    }
    expected
}

/// Expected bytes of the `MAX_DISTANCE` vector: a 32 KiB window repeated.
fn max_distance_expected() -> Vec<u8> {
    let window: Vec<u8> = (0..32_768u32)
        .map(|index| ((index * 131 + 7) & 0xFF) as u8)
        .collect();
    let mut expected = window.clone();
    expected.extend_from_slice(&window);
    expected.extend_from_slice(b"tail");
    expected
}

/// Expected bytes of the `LONG_MATCH` vector.
fn long_match_expected() -> Vec<u8> {
    let mut expected = Vec::new();
    for _ in 0..256 {
        expected.extend_from_slice(b"0123456789abcdef");
    }
    expected.extend((0..2000u32).map(|index| ((index * 7 + index / 7) & 0xFF) as u8));
    for _ in 0..256 {
        expected.extend_from_slice(b"0123456789abcdef");
    }
    expected
}

#[test]
fn inflate_stored_block_zlib_and_raw() {
    assert_eq!(
        inflate_zlib(STORED, InflateLimits::default()).unwrap(),
        STORED_DATA
    );
    assert_eq!(
        inflate_deflate(STORED_RAW, InflateLimits::default()).unwrap(),
        STORED_DATA
    );
}

#[test]
fn inflate_fixed_huffman_block() {
    assert_eq!(
        inflate_zlib(FIXED, InflateLimits::default()).unwrap(),
        FIXED_DATA
    );
    assert_eq!(
        inflate_deflate(FIXED_RAW, InflateLimits::default()).unwrap(),
        FIXED_DATA
    );
}

#[test]
fn inflate_dynamic_huffman_block() {
    let expected = dynamic_expected();
    assert_eq!(
        inflate_zlib(DYNAMIC, InflateLimits::default()).unwrap(),
        expected
    );
    assert_eq!(
        inflate_deflate(DYNAMIC_RAW, InflateLimits::default()).unwrap(),
        expected
    );
}

#[test]
fn inflate_long_matches_and_maximum_distance() {
    assert_eq!(
        inflate_zlib(LONG_MATCH, InflateLimits::default()).unwrap(),
        long_match_expected()
    );
    assert_eq!(
        inflate_zlib(MAX_DISTANCE, InflateLimits::default()).unwrap(),
        max_distance_expected()
    );
}

#[test]
fn inflate_rejects_bad_adler_and_truncation() {
    assert!(matches!(
        inflate_zlib(BAD_ADLER, InflateLimits::default()),
        Err(image::InflateError::AdlerMismatch { .. })
    ));
    assert_eq!(
        inflate_zlib(TRUNCATED, InflateLimits::default()),
        Err(image::InflateError::TruncatedInput)
    );
}

#[test]
fn inflate_output_limit_is_enforced() {
    assert!(matches!(
        inflate_zlib(DYNAMIC, InflateLimits::new(8)),
        Err(image::InflateError::OutputLimitExceeded { limit: 8 })
    ));
    assert!(inflate_zlib(DYNAMIC, InflateLimits::new(1 << 20)).is_ok());
}

/// Decodes a generated fixture and compares it byte-for-byte with the expected
/// RGBA file produced by the independent Python encoder.
macro_rules! fixture_test {
    ($name:ident) => {
        #[test]
        fn $name() {
            let png = include_bytes!(concat!("fixtures/png/", stringify!($name), ".png"));
            let expected = include_bytes!(concat!("fixtures/png/", stringify!($name), ".rgba"));
            let image = decode(png)
                .unwrap_or_else(|error| panic!("decoding {}: {error}", stringify!($name)));
            assert_eq!(
                image.as_rgba(),
                &expected[..],
                "decoded pixels differ for {}",
                stringify!($name)
            );
        }
    };
}

