#[test]
fn decodes_the_real_pipeline_png_and_matches_the_golden_rgba() {
    let png = include_bytes!("fixtures/png/basic.png");
    assert_eq!(detect_format(png), ImageFormat::Png);
    let started = std::time::Instant::now();
    let image = decode(png).expect("the pipeline PNG must decode");
    eprintln!(
        "decoded basic.png (800x600, {} bytes) in {:?}",
        png.len(),
        started.elapsed()
    );
    assert_eq!(image.dimensions(), (800, 600));

    let golden_path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/phase4/basic.rgba"
    );
    let golden = std::fs::read(golden_path)
        .unwrap_or_else(|error| panic!("cannot read {golden_path}: {error}"));
    assert_eq!(golden.len(), 800 * 600 * 4);
    assert_eq!(
        image.as_rgba(),
        &golden[..],
        "decoding basic.png does not reproduce basic.rgba"
    );
}

#[test]
fn rejects_bad_signature_and_unsupported_formats() {
    assert_eq!(
        decode(b"\x89PNG").unwrap_err(),
        ImageError::InvalidSignature
    );
    assert_eq!(decode(b"").unwrap_err(), ImageError::InvalidSignature);
    assert!(matches!(
        decode(b"GIF89a-not-really").unwrap_err(),
        ImageError::UnsupportedFormat {
            format: ImageFormat::Gif
        }
    ));
    assert!(matches!(
        decode(&[0xFF, 0xD8, 0xFF, 0xE0]).unwrap_err(),
        ImageError::UnsupportedFormat {
            format: ImageFormat::Jpeg
        }
    ));
}

/// Locates the byte offset of a chunk's CRC field in a PNG fixture.
fn idat_crc_offset(png: &[u8]) -> usize {
    let mut position = 8usize;
    loop {
        let length = u32::from_be_bytes([
            png[position],
            png[position + 1],
            png[position + 2],
            png[position + 3],
        ]) as usize;
        let kind = &png[position + 4..position + 8];
        if kind == b"IDAT" {
            return position + 8 + length;
        }
        position += 12 + length;
    }
}

#[test]
fn rejects_corrupted_chunk_crc() {
    let mut png = include_bytes!("fixtures/png/filters_rgba8.png").to_vec();
    let crc_offset = idat_crc_offset(&png);
    png[crc_offset + 3] ^= 0xFF;
    assert!(matches!(
        decode(&png).unwrap_err(),
        ImageError::CrcMismatch { .. }
    ));
}

#[test]
fn every_truncation_of_a_png_is_an_error_and_never_panics() {
    let png = include_bytes!("fixtures/png/gray8.png");
    for length in 0..png.len() {
        let truncated = &png[..length];
        assert!(
            decode(truncated).is_err(),
            "a {length}-byte prefix must not decode"
        );
    }
    assert!(decode(png).is_ok());
}

#[test]
fn defensive_limits_are_enforced() {
    let png = include_bytes!("fixtures/png/gray8.png");
    // 4x3 image: dimension limit of 2 must fail.
    assert!(matches!(
        decode_with_limits(png, &PngLimits::new(2, 100, 1 << 20, 1 << 20)).unwrap_err(),
        ImageError::LimitExceeded { .. }
    ));
    // 12 pixels but a 5-pixel budget must fail.
    assert!(matches!(
        decode_with_limits(png, &PngLimits::new(16_384, 5, 1 << 20, 1 << 20)).unwrap_err(),
        ImageError::LimitExceeded { .. }
    ));
    // IHDR is 13 bytes: a 10-byte chunk limit must fail.
    assert!(matches!(
        decode_with_limits(png, &PngLimits::new(16_384, 1 << 20, 10, 1 << 20)).unwrap_err(),
        ImageError::LimitExceeded { .. }
    ));
    // A 4-byte IDAT budget must fail before decompression.
    assert!(matches!(
        decode_with_limits(png, &PngLimits::new(16_384, 1 << 20, 1 << 20, 4)).unwrap_err(),
        ImageError::LimitExceeded { .. }
    ));
    // The default limits accept the fixture.
    assert!(decode(png).is_ok());
}

/// Deterministic mini-fuzz: 200 mutated PNGs and 200 mutated zlib streams must
/// come back as `Ok`/`Err`, never as a panic/abort.
#[test]
fn mini_fuzz_two_hundred_mutations_never_panics() {
    let png_samples: [&[u8]; 2] = [
        include_bytes!("fixtures/png/filters_rgba8.png"),
        include_bytes!("fixtures/png/interlaced_rgba8.png"),
    ];
    let zlib_samples: [&[u8]; 3] = [STORED, FIXED, DYNAMIC];
    let mut state = 0x1234_5678u32;
    let mut next = || {
        state = state.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        state
    };

    for iteration in 0..200usize {
        // --- PNG mutations ---
        let source = png_samples[iteration % png_samples.len()];
        let mut mutated = source.to_vec();
        for _ in 0..2 {
            let position = (next() as usize) % mutated.len();
            let value = (next() >> 24) as u8;
            mutated[position] ^= value | 1;
        }
        if iteration % 5 == 0 {
            mutated.truncate(mutated.len() / 2);
        }
        let _ = decode(&mutated);

        // --- zlib mutations ---
        let source = zlib_samples[iteration % zlib_samples.len()];
        let mut mutated = source.to_vec();
        for _ in 0..2 {
            let position = (next() as usize) % mutated.len();
            let value = (next() >> 24) as u8;
            mutated[position] ^= value | 1;
        }
        let _ = inflate_zlib(&mutated, InflateLimits::new(1 << 20));
    }
}

#[test]
fn all_generated_fixtures_are_detected_as_png() {
    let samples: [&[u8]; 4] = [
        include_bytes!("fixtures/png/gray8.png"),
        include_bytes!("fixtures/png/palette8.png"),
        include_bytes!("fixtures/png/interlaced_rgba8.png"),
        include_bytes!("fixtures/png/basic.png"),
    ];
    for png in samples {
        assert_eq!(detect_format(png), ImageFormat::Png);
    }
}
